PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,price REAL NOT NULL CHECK(price >= 0),image_url TEXT NOT NULL,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,total REAL NOT NULL CHECK(total >= 0),status TEXT NOT NULL DEFAULT 'new',delivery_address TEXT NOT NULL,delivery_date TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity > 0),price REAL NOT NULL CHECK(price >= 0));
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id INTEGER REFERENCES products(id) ON DELETE SET NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),text TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE VIEW IF NOT EXISTS v_order_summary AS SELECT o.id,u.name AS customer,u.email,o.total,o.status,o.delivery_date FROM orders o JOIN users u ON u.id=o.user_id;
CREATE VIEW IF NOT EXISTS v_popular_products AS SELECT p.id,p.name,COALESCE(SUM(oi.quantity),0) AS sold FROM products p LEFT JOIN order_items oi ON oi.product_id=p.id GROUP BY p.id,p.name ORDER BY sold DESC;
CREATE VIEW IF NOT EXISTS v_customer_orders AS SELECT u.id AS user_id,u.name,COUNT(o.id) AS orders_count,COALESCE(SUM(o.total),0) AS spent FROM users u LEFT JOIN orders o ON o.user_id=u.id GROUP BY u.id,u.name;
CREATE VIEW IF NOT EXISTS v_product_ratings AS SELECT p.id,p.name,ROUND(AVG(r.rating),1) AS rating,COUNT(r.id) AS reviews_count FROM products p LEFT JOIN reviews r ON r.product_id=p.id GROUP BY p.id,p.name;
CREATE VIEW IF NOT EXISTS v_daily_sales AS SELECT substr(created_at,1,10) AS sale_date,COUNT(*) AS orders_count,SUM(total) AS revenue FROM orders GROUP BY substr(created_at,1,10) ORDER BY sale_date DESC;
